    # Locate the rectangular rooms partitioned by the 8-valued grid lines.
    rb, cb = [], []
    start = 0
    for r in range(h):
        if all(v == 8 for v in grid[r]):
            if start < r:
                rb.append((start, r))
            start = r + 1
    if start < h:
        rb.append((start, h))

    start = 0
    for c in range(w):
        if all(grid[r][c] == 8 for r in range(h)):
            if start < c:
                cb.append((start, c))
            start = c + 1
    if start < w:
        cb.append((start, w))

    points = {2: [], 3: []}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] in points:
                        points[grid[r][c]].append((i, j))

    # Draw between pairs of same-colored markers that share a row or column.
    painted = {2: set(), 3: set()}
    for color, pts in points.items():
        for a in range(len(pts)):
            r1, c1 = pts[a]
            for b in range(a + 1, len(pts)):
                r2, c2 = pts[b]
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[color].add((r1, c))
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[color].add((r, c1))

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            color = 6 if (i, j) in painted[2] and (i, j) in painted[3] else (
                2 if (i, j) in painted[2] else 3 if (i, j) in painted[3] else 0
            )
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = color
    return out
